def test_top_two():
    probs = [0.5, 0.3, 0.15, 0.05]
    assert solution.nucleus_indices(probs, 0.8) == [0, 1]

def test_dominant_token():
    assert solution.nucleus_indices([0.95, 0.03, 0.02], 0.9) == [0]

def test_p_one_keeps_all():
    assert solution.nucleus_indices([0.25, 0.25, 0.25, 0.25], 1.0) == [0, 1, 2, 3]

def test_p_zero_keeps_first():
    assert solution.nucleus_indices([0.2, 0.5, 0.3], 0.0) == [1]

def test_tie_order():
    assert solution.nucleus_indices([0.5, 0.5], 0.5) == [0]
    assert solution.nucleus_indices([0.5, 0.5], 0.75) == [0, 1]

def test_does_not_mutate():
    probs = [0.4, 0.35, 0.25]
    before = probs[:]
    out = solution.nucleus_indices(probs, 0.7)
    assert probs == before
    assert out is not probs
